def decide(answer):
    """Map one ElicitResult dict to 'terminate', 'answered-no', 'declined' or 'dismissed'."""
    if answer["action"] == "accept":
        if answer.get("content", {}).get("confirm") is True:
            return "terminate"
        return "answered-no"
    if answer["action"] == "decline":
        return "declined"
    return "dismissed"
